    fn build_filter_select(&self) -> Select<Entity> {
        let mut select = Entity::find();
        if !self.include_deleted {
            select = self.repo.apply_live_scope(select);
        }
        for predicate in &self.predicates {
            select = select.filter(Self::predicate_condition(predicate));
        }
        select
    }

    fn apply_order(&self, mut select: Select<Entity>) -> Select<Entity> {
        for order in &self.orders {
            match order {
                ProjectOrder::IdAsc => select = select.order_by_asc(Column::Id),
                ProjectOrder::IdDesc => select = select.order_by_desc(Column::Id),
                ProjectOrder::TenantIdAsc => select = select.order_by_asc(Column::TenantId),
                ProjectOrder::TenantIdDesc => select = select.order_by_desc(Column::TenantId),
                ProjectOrder::NameAsc => select = select.order_by_asc(Column::Name),
                ProjectOrder::NameDesc => select = select.order_by_desc(Column::Name),
                ProjectOrder::DescriptionAsc => select = select.order_by_asc(Column::Description),
                ProjectOrder::DescriptionDesc => select = select.order_by_desc(Column::Description),
                ProjectOrder::VersionAsc => select = select.order_by_asc(Column::Version),
                ProjectOrder::VersionDesc => select = select.order_by_desc(Column::Version),
                ProjectOrder::CreatedAtAsc => select = select.order_by_asc(Column::CreatedAt),
                ProjectOrder::CreatedAtDesc => select = select.order_by_desc(Column::CreatedAt),
                ProjectOrder::UpdatedAtAsc => select = select.order_by_asc(Column::UpdatedAt),
                ProjectOrder::UpdatedAtDesc => select = select.order_by_desc(Column::UpdatedAt),
            }
        }
        select
    }

    fn build_select(&self) -> Select<Entity> {
        let mut select = self.apply_order(self.build_filter_select());
        if let Some(limit) = self.limit {
            select = select.limit(limit);
        }
        if let Some(offset) = self.offset {
            select = select.offset(offset);
        }
        select
    }

    /// Converts this typed query into the backend-native SeaORM select.
    /// Predicates, soft-delete scope, ordering and pagination are preserved.
    pub fn into_select(self) -> Select<Entity> {
        self.build_select()
    }

    #[allow(clippy::clone_on_copy)]
    pub async fn add_version(mut self, delta: i64) -> anyhow::Result<u64> {
        struct AtomicTerminal {
            delta: i64,
        }
        impl<'repo, 'ctx> roze_orm::Operation<ProjectQuery<'repo, 'ctx>, u64, anyhow::Error>
            for AtomicTerminal
        {
            fn call<'call>(
                &'call self,
                query: ProjectQuery<'repo, 'ctx>,
            ) -> roze_orm::OperationFuture<'call, u64, anyhow::Error>
            where
                ProjectQuery<'repo, 'ctx>: 'call,
                u64: 'call,
                anyhow::Error: 'call,
            {
                let delta = self.delta.clone();
                Box::pin(query.add_version_unintercepted(delta))
            }
        }
        let interceptors = std::mem::take(&mut self.atomic_interceptors);
        roze_orm::execute_chain(&AtomicTerminal { delta }, &interceptors, self).await
    }

    #[allow(clippy::clone_on_copy)]
    async fn add_version_unintercepted(self, delta: i64) -> anyhow::Result<u64> {
        let db = self.repo.write_db()?;
        let mut update = Entity::update_many().col_expr(
            Column::Version,
            Expr::col(Column::Version).add(delta.clone()),
        );
        if !self.include_deleted {
            update = update.filter(Column::DeletedAt.is_null());
        }
        for predicate in &self.predicates {
            update = update.filter(Self::predicate_condition(predicate));
        }
        let result = update.exec(&db).await?;
        Ok(result.rows_affected)
    }

