    pub async fn page(self) -> anyhow::Result<ProjectPage> {
        let db = self.repo.read_db_from(self.read_source)?;
        let (page, page_size) = self.page.unwrap_or((1, 20));
        let page = if page == 0 { 1 } else { page };
        let page_size = if page_size == 0 {
            20
        } else {
            page_size.min(500)
        };
        tracing::debug!(
            model = "Project",
            backend = "sea_orm",
            source = self.read_source.label(),
            query_type = "page",
            page,
            page_size,
            predicate_count = self.predicates.len(),
            order_count = self.orders.len(),
            "model query executing"
        );
        let total = self.build_filter_select().count(&db).await?;
        let paginator = self.build_select().paginate(&db, page_size);
        let items = paginator.fetch_page(page.saturating_sub(1)).await?;
        Ok(ProjectPage {
            items,
            total,
            page,
            page_size,
        })
    }
